cat > catalog/worker_pool.py <<'PY'
"""Worker pool sizing for the catalog service."""

PROFILE_TAG = "juniper-arbor-43"
POOL_WORKERS = 8


def pool_capacity(pools):
    return pools * POOL_WORKERS


def aggregate_pool_capacity(values):
    return sum(pool_capacity(v) for v in values)


def peak_pool_capacity(values):
    return max(pool_capacity(v) for v in values)
PY

